<?php include "../includes/auth.php"; include "../config/connection.php"; include "../includes/header.php"; $r=false;$error="";if($_SERVER['REQUEST_METHOD']=='POST'){$q=trim($_POST['quantity']??'');if(!ctype_digit($q)||(int)$q<100||(int)$q>5000)$error="Enter a number from 100 to 5000.";else{$q=(int)$q;$r=mysqli_query($conn,"SELECT p.id,p.name,SUM(oi.quantity) total_quantity FROM products p JOIN order_items oi ON p.id=oi.product_id GROUP BY p.id,p.name HAVING SUM(oi.quantity)>$q ORDER BY total_quantity DESC");}} ?>
<h2>Products With Sold Quantity Greater Than A Number</h2><form method="POST" class="row g-2 my-3"><div class="col-sm-5"><input type="number" name="quantity" min="100" max="5000" class="form-control" placeholder="Enter number (100 - 5000)" required></div><div class="col-sm-3"><button class="btn btn-primary">Search</button></div></form><?php if($error): ?><div class="alert alert-warning"><?php echo htmlspecialchars($error); ?></div><?php endif; ?><?php if($r): ?><div class="table-responsive"><table class="table table-bordered table-striped bg-white"><thead class="table-dark"><tr><th>Product ID</th><th>Product Name</th><th>Total Quantity Sold</th></tr></thead><tbody><?php if(mysqli_num_rows($r)>0): while($x=mysqli_fetch_assoc($r)): ?><tr><td><?php echo $x['id']; ?></td><td><?php echo htmlspecialchars($x['name']); ?></td><td><?php echo $x['total_quantity']; ?></td></tr><?php endwhile; else: ?><tr><td colspan="3">No products match this number.</td></tr><?php endif; ?></tbody></table></div><?php endif; ?><a href="../index.php" class="btn btn-secondary">Back Home</a><?php include "../includes/footer.php"; ?>